update public.learning_paths
set
  title = '2-D Design (Foundation Year)',
  goal = '2-D Design (Foundation Year)',
  summary = '2-D Design (Foundation Year) teaches the basic visual vocabulary students manipulate in every composition and the organizing principles that turn visual parts into intentional compositions. Students study how flat surfaces imply space and visual tension; placement, scale, margins, and the path a viewer''s eye follows; value structure without hue; color vocabulary and how colors change through adjacency, contrast, transparency, and optical mixing; pattern, rhythm, and modular systems; craft and presentation; research and iteration; critique language; and a portfolio that demonstrates growth, process, craft, and command of visual language.',
